description:
A table `accounts(name TEXT PRIMARY KEY, balance INTEGER NOT NULL)` holds balances in pennies. Write `transfer(con, frm, to, amount)`:

- `amount` must be a positive whole number, otherwise `ValueError` and nothing changes;
- both accounts must exist, otherwise `KeyError` and nothing changes;
- `frm` must have at least `amount`, otherwise `ValueError("insufficient funds")` and nothing changes;
- otherwise move the money in **one transaction**, so that either both balances change or neither does.

Also write `balances(con)` returning a dictionary of name to balance.

starter.solution.py:
import sqlite3


def transfer(con, frm, to, amount):
    con.execute("UPDATE accounts SET balance = balance - ? WHERE name = ?", (amount, frm))
    con.execute("UPDATE accounts SET balance = balance + ? WHERE name = ?", (amount, to))


def balances(con):
    return {}

solution.solution.py:
import sqlite3


def balances(con):
    return dict(con.execute("SELECT name, balance FROM accounts"))


def transfer(con, frm, to, amount):
    if not isinstance(amount, int) or isinstance(amount, bool) or amount <= 0:
        raise ValueError("amount must be a positive whole number")
    with con:
        row = con.execute("SELECT balance FROM accounts WHERE name = ?", (frm,)).fetchone()
        if row is None:
            raise KeyError(frm)
        if con.execute("SELECT 1 FROM accounts WHERE name = ?", (to,)).fetchone() is None:
            raise KeyError(to)
        if row[0] < amount:
            raise ValueError("insufficient funds")
        con.execute("UPDATE accounts SET balance = balance - ? WHERE name = ?", (amount, frm))
        con.execute("UPDATE accounts SET balance = balance + ? WHERE name = ?", (amount, to))

unitTests:
import sqlite3

def bank():
    con = sqlite3.connect(":memory:")
    con.execute("CREATE TABLE accounts (name TEXT PRIMARY KEY, balance INTEGER NOT NULL)")
    con.executemany("INSERT INTO accounts VALUES (?, ?)", [("ada", 1000), ("bob", 200)])
    con.commit()
    return con

@test("a transfer moves the money")
def _():
    con = bank()
    transfer(con, "ada", "bob", 300)
    check_eq(balances(con), {"ada": 700, "bob": 500})

@test("insufficient funds changes nothing")
def _():
    con = bank()
    check_raises(ValueError, transfer, con, "bob", "ada", 201)
    check_eq(balances(con), {"ada": 1000, "bob": 200})

@test("unknown accounts change nothing")
def _():
    con = bank()
    check_raises(KeyError, transfer, con, "ada", "zed", 10)
    check_raises(KeyError, transfer, con, "zed", "ada", 10)
    check_eq(balances(con), {"ada": 1000, "bob": 200})

@test("bad amounts refused")
def _():
    con = bank()
    for bad in [0, -5, 2.5, True]:
        check_raises(ValueError, transfer, con, "ada", "bob", bad)
    check_eq(balances(con), {"ada": 1000, "bob": 200})

@test("the change is committed")
def _():
    con = bank()
    transfer(con, "ada", "bob", 1)
    con.rollback()
    check_eq(balances(con), {"ada": 999, "bob": 201})

